-- Seed the owner's approved standards only. No employee is assigned or published.
INSERT INTO agency_learning_catalogs (agency_id,catalog_json) SELECT id, JSON_OBJECT('version',1,'rates',JSON_ARRAY(),'packages',JSON_ARRAY()) FROM agencies WHERE slug='nlu' ON DUPLICATE KEY UPDATE agency_id=VALUES(agency_id);
UPDATE agency_learning_catalogs c JOIN agencies a ON a.id=c.agency_id SET c.catalog_json=JSON_SET(c.catalog_json,'$.tiers',CAST('[{"id": "L1", "name": "Tutor Assistant", "description": "HS student / new tutor / follows provided plan", "pay": {"virtual": 1800, "in-person": 1900, "small-group": null}, "fees": {"virtual": 3000, "in-person": 3500, "small-group": null}}, {"id": "L2", "name": "Developing Tutor", "description": "Experienced HS tutor, college student, bachelor’s with little experience", "pay": {"virtual": 2000, "in-person": 2100, "small-group": null}, "fees": {"virtual": 3500, "in-person": 4000, "small-group": null}}, {"id": "L3", "name": "Professional Tutor", "description": "Bachelor’s + experience; experienced tutor; master’s with little experience", "pay": {"virtual": 2300, "in-person": 2500, "small-group": null}, "fees": {"virtual": 4000, "in-person": 4500, "small-group": null}}, {"id": "L4", "name": "Advanced Tutor", "description": "Teacher, master’s + experience, experienced interventionist", "pay": {"virtual": 2700, "in-person": 2900, "small-group": null}, "fees": {"virtual": 5000, "in-person": 5500, "small-group": null}}, {"id": "L5", "name": "Educational Specialist", "description": "Experienced licensed teacher, interventionist, SPED/reading/math specialist", "pay": {"virtual": 3200, "in-person": 3500, "small-group": null}, "fees": {"virtual": 6000, "in-person": 6500, "small-group": null}}]' AS JSON)) WHERE a.slug='nlu' AND COALESCE(JSON_LENGTH(JSON_EXTRACT(c.catalog_json,'$.tiers')),0)=0;

-- Distinct codes let a dual-role employee retain all counseling compensation rates.
INSERT INTO payroll_service_code_rules (agency_id,service_code,category,other_slot,unit_to_hour_multiplier,duration_minutes,counts_for_tier,tier_credit_multiplier,pay_divisor,pay_rate_unit,credit_value,show_in_rate_sheet)
SELECT a.id,c.code,'other',1,1,60,0,0,1,'per_hour',1,1 FROM agencies a CROSS JOIN (SELECT 'TUTORING VIRTUAL' AS code UNION ALL SELECT 'TUTORING IN PERSON') c WHERE a.slug='nlu'
ON DUPLICATE KEY UPDATE service_code=VALUES(service_code);
